import { test, expect } from "bun:test";

test("Fast File Reading", async () => {
  const f = Bun.file('test_bun.sh');
  const text = await f.text();
  const lineCount = text.split('\n').length;
  expect(lineCount).toBe(42);
});

test("Native Fetch API", async () => {
  const res = await fetch('https://jsonplaceholder.typicode.com/todos/1');
  const data = await res.json();
  expect(data).toEqual({
    userId: 1,
    id: 1,
    title: "delectus aut autem",
    completed: false,
  });
});

test("Password Hashing", async () => {
  const password = 'password123';
  const hash = await Bun.password.hash(password);
  const verify = await Bun.password.verify(password, hash);
  expect(verify).toBe(true);
});

test("High-Resolution Timer", async () => {
  const start = Bun.nanoseconds();
  await new Promise(r => setTimeout(r, 100));
  const end = Bun.nanoseconds();
  const timeTakenMs = (end - start) / 1000000;
  expect(timeTakenMs).toBeGreaterThanOrEqual(100);
});

test("JSON Manipulation", async () => {
  const data = JSON.parse('{"users": [{"id": 1, "name": "Alice"}, {"id": 2, "name": "Bob"}]}');
  const updated = data.users.map(u => ({...u, active: true}));
  const result = JSON.stringify(updated);
  expect(result).toBe('[{"id":1,"name":"Alice","active":true},{"id":2,"name":"Bob","active":true}]');
});

